-- Hyprland config (Lua format, Hyprland >= 0.55)
-- Based on /usr/share/hypr/hyprland.lua. Wiki: https://wiki.hypr.land/Configuring/Start/
-- See ~/config.md for the full install/config record.


------------------
---- MONITORS ----
------------------

-- Monitor layout lives in monitors.lua so monique can manage it.
-- Edit it with the monique GUI (SUPER + SHIFT + M) rather than by hand.
require("monitors")

-- Machine-specific values (GPU, monitor names, VNC output), generated by chezmoi from
-- .chezmoidata/hosts.toml. Missing values fall back to generic behaviour below.
local host = require("host")


---------------------
---- MY PROGRAMS ----
---------------------

local terminal    = "ghostty"
local menu        = "vicinae toggle"
local clipboard   = "cliphist list | vicinae dmenu -n Clipboard -p 'Search clipboard' | cliphist decode | wl-copy"


-------------------------------
---- ENVIRONMENT VARIABLES ----
-------------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

-- NVIDIA, only on machines running the NVIDIA driver (on hephaestus the 3080 drives both
-- monitors and the AMD iGPU is unused). drm_devices pins Hyprland to one GPU; on hephaestus
-- it's /dev/dri/nvidia-dgpu, a stable symlink from /etc/udev/rules.d/61-gpu-symlinks.rules
if host.drm_devices then
    hl.env("AQ_DRM_DEVICES", host.drm_devices)
end
if host.nvidia then
    hl.env("LIBVA_DRIVER_NAME", "nvidia")
    hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
    hl.env("NVD_BACKEND", "direct")
end

-- Toolkits: prefer Wayland
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("QT_QPA_PLATFORM", "wayland;xcb")
hl.env("QT_WAYLAND_DISABLE_WINDOWDECORATION", "1")
hl.env("QS_ICON_THEME", "MacTahoe-dark")   -- icon theme for Quickshell (tray, dock fallback icons)
hl.env("GDK_BACKEND", "wayland,x11,*")
hl.env("SDL_VIDEODRIVER", "wayland")
hl.env("MOZ_ENABLE_WAYLAND", "1")


-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function ()
    -- Make the Wayland session visible to systemd/dbus-activated services (portals, etc.)
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP HYPRLAND_INSTANCE_SIGNATURE")

    hl.exec_cmd("hyprpaper")                                      -- wallpaper
    hl.exec_cmd("hypridle")                                       -- idle -> hyprlock
    if host.wayvnc_output then
        hl.exec_cmd("wayvnc --output=" .. host.wayvnc_output)     -- VNC for Termix, ~/.config/wayvnc/config sets the address
    end
    hl.exec_cmd("dock-icons --quiet; qs")                         -- dock icon tiles for new apps, then quickshell (bar, notifications, dock)
    hl.exec_cmd("vicinae server")                                 -- launcher daemon
    hl.exec_cmd("udiskie")                                        -- automount USB drives
    hl.exec_cmd("moniqued")                                       -- monique hotplug profile daemon
    hl.exec_cmd("keyd-hypr-mapper")                               -- per-app Cmd mappings + keyboard mode (keyd)
    hl.exec_cmd("librepods --start-minimized")                    -- AirPods controls (tray), ~/.local/bin

    hl.dispatch(hl.dsp.focus({ workspace = 1 }))                  -- start focused on the primary monitor
    hl.exec_cmd("wl-paste --type text --watch cliphist store")    -- clipboard history (text)
    hl.exec_cmd("wl-paste --type image --watch cliphist store")   -- clipboard history (images)
end)


