---------------
---- INPUT ----
---------------

hl.config({
    input = {
        kb_layout  = "us",
        kb_variant = "",
        kb_model   = "",
        -- No modifier swapping here: keyd (/etc/keyd) handles the macOS-style Cmd key
        -- at the device level, so it also applies on TTYs and the greeter.
        kb_options = "",
        kb_rules   = "",

        follow_mouse = 1,
        sensitivity  = 0,           -- -1.0 to 1.0; with "flat" this is a constant speed multiplier
        accel_profile = "flat",     -- no mouse acceleration (1:1 movement)

        touchpad = {
            natural_scroll = false,
        },
    },
})


---------------------
---- KEYBINDINGS ----
---------------------

-- ALT is "Opt", and it's the window-manager key. Cmd is keyd's app-shortcut layer: Cmd+<key> becomes
-- the Linux Ctrl shortcut (copy, paste, save, new tab, ...), so it never reaches these binds.
-- Only Cmd+Space (launcher) and Cmd+Shift+V (clipboard history) come through, as SUPER+SPACE and
-- SUPER+SHIFT+V (keyd maps them in /etc/keyd/macos-layers).
local mainMod = "ALT"

-- Apps (everything else launches from vicinae)
hl.bind(mainMod .. " + T",         hl.dsp.exec_cmd(terminal), { description = "Apps: Terminal" })
hl.bind("SUPER + SPACE",           hl.dsp.exec_cmd(menu), { description = "Apps: Launcher" })          -- Cmd+Space (keyd), like Spotlight
hl.bind("SUPER + SHIFT + V",       hl.dsp.exec_cmd(clipboard), { description = "Apps: Clipboard history" })     -- Cmd+Shift+V (keyd)

-- Windows / session (macOS-style)
hl.bind(mainMod .. " + Q",                hl.dsp.window.close(), { description = "Windows: Close window" })
hl.bind(mainMod .. " + CTRL + Q",         hl.dsp.exec_cmd("loginctl lock-session"), { description = "Session: Lock screen" })
hl.bind(mainMod .. " + L",                hl.dsp.exec_cmd("loginctl lock-session"), { description = "Session: Lock screen" })
hl.bind(mainMod .. " + SHIFT + Q",        hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"), { description = "Session: Log out" })
hl.bind(mainMod .. " + SHIFT + SPACE",    hl.dsp.window.float({ action = "toggle" }), { description = "Windows: Toggle floating" })
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo(), { description = "Windows: Pseudotile" })
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"), { description = "Windows: Toggle split direction" })    -- dwindle only
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("wayvncctl output-cycle"), { description = "Session: Cycle VNC monitor" })  -- VNC: show the next monitor

-- Keyboard shortcuts cheat sheet (Quickshell Cheatsheet.qml). It lists every bind live from `hyprctl binds -j`,
-- grouped by the "Group: Name" description, so give new binds a description to keep it complete.
hl.bind(mainMod .. " + slash", hl.dsp.exec_cmd("qs ipc call cheatsheet toggle"), { description = "Shell: Keyboard shortcuts" })

-- Move focus with Opt + arrow keys (Cmd + arrows are Home/End in apps)
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }), { description = "Focus: Move focus" })
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus: Move focus" })
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }), { description = "Focus: Move focus" })
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }), { description = "Focus: Move focus" })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }), { description = "Workspaces: Switch to workspace" })
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }), { description = "Workspaces: Move window to workspace" })
end

-- Special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"), { description = "Workspaces: Toggle scratchpad" })
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }), { description = "Workspaces: Move window to scratchpad" })

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Workspaces: Next / previous workspace" })
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }), { description = "Workspaces: Next / previous workspace" })

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true, description = "Windows: Move window" })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Windows: Resize window" })

-- Screenshots (~/.local/bin/screenshot): saved to ~/Pictures/Screenshots and copied; click the notification to annotate in Satty
hl.bind("Print",          hl.dsp.exec_cmd("screenshot region"), { description = "Screenshots: Region or window" })   -- drag a region, or click a window
hl.bind("SHIFT + Print",  hl.dsp.exec_cmd("screenshot full"), { description = "Screenshots: Whole monitor" })     -- monitor under the mouse
hl.bind("CTRL + Print",   hl.dsp.exec_cmd("screenshot window"), { description = "Screenshots: Focused window" })   -- focused window

-- Media keys (PipeWire via wpctl, players via playerctl)
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true, description = "Media: Volume up" })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true, description = "Media: Volume down" })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true, description = "Media: Mute" })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true, repeating = true, description = "Media: Mute microphone" })
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true, description = "Media: Next track" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Media: Play / pause" })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Media: Play / pause" })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true, description = "Media: Previous track" })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- Workspace 1 on the primary monitor, 2 on the secondary (from host.lua; on hephaestus the
-- Alienware ultrawide and the LG 1080p). Matched by description because the DP-N names can
-- change on replug. Machines without them set just get Hyprland's default placement.
if host.primary_monitor then
    hl.workspace_rule({ workspace = "1", monitor = host.primary_monitor, default = true })
end
if host.secondary_monitor then
    hl.workspace_rule({ workspace = "2", monitor = host.secondary_monitor, default = true })
end

hl.window_rule({
    -- Ignore maximize requests from all apps
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Blur behind the Quickshell dock's translucent background
hl.layer_rule({
    name  = "dock-blur",
    match = { namespace = "^quickshell-dock$" },

    blur         = true,
    ignore_alpha = 0.05,  -- blur the 10% glass, not the fully transparent space around it
})

-- Blur behind notification banners
hl.layer_rule({
    name  = "notifications-blur",
    match = { namespace = "^quickshell-notifications$" },

    blur         = true,
    ignore_alpha = 0.05,
})

-- Blur behind the Quickshell popovers (Control Center, calendar, workspace overview); they animate
-- themselves, so skip Hyprland's layer fade
hl.layer_rule({
    name  = "popover-blur",
    match = { namespace = "^quickshell-popover$" },

    blur         = true,
    ignore_alpha = 0.05,
    no_anim      = true,
})

-- Blur behind the Quickshell polkit dialog; ignore_alpha above the scrim's 22% so only the sheet is blurred
hl.layer_rule({
    name  = "polkit-blur",
    match = { namespace = "^quickshell-polkit$" },

    blur         = true,
    ignore_alpha = 0.3,
    no_anim      = true,
})

-- Blur behind the Quickshell keyboard shortcuts cheat sheet (same setup as polkit-blur)
hl.layer_rule({
    name  = "cheatsheet-blur",
    match = { namespace = "^quickshell-cheatsheet$" },

    blur         = true,
    ignore_alpha = 0.3,
    no_anim      = true,
})

hl.window_rule({
    name  = "float-satty",
    match = { class = "com.gabm.satty" },

    float  = true,
    center = true,
})

hl.window_rule({
    name  = "float-monique",
    match = { class = "com.github.monique" },

    float = true,
})
